export { AdminPayments };

import React, { useState, useEffect } from 'react';
import { useAdmin } from '../context/AdminContext';
import { AdminLayout } from '../components/AdminLayout';
import UserDetailsModal from '../components/UserDetailsModal';
import AdminMessageModal from '../components/AdminMessageModal';
import MessageBanner from '../components/MessageBanner';
import '../styles/admin.css';

export const AdminUsers = () => {
  const { fetchUsers, suspendUser, unsuspendUser, deleteUser, loading, error } = useAdmin();
  
  const [users, setUsers] = useState([]);
  const [localError, setLocalError] = useState(null);
  const [pagination, setPagination] = useState({});
  const [currentPage, setCurrentPage] = useState(1);
  const [search, setSearch] = useState('');
  const [role, setRole] = useState('');
  const [status, setStatus] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [modalActive, setModalActive] = useState(false);
  const [actionType, setActionType] = useState(null);
  const [reason, setReason] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  
  // New modals for Phase 5C
  const [detailsModalOpen, setDetailsModalOpen] = useState(false);
  const [messageModalOpen, setMessageModalOpen] = useState(false);
  const [detailsUser, setDetailsUser] = useState(null);
  const [messageUser, setMessageUser] = useState(null);
  const [confirm, setConfirm] = useState({ open: false, title: '', message: '', onConfirm: null });

  const loadUsers = async (page = 1, filters = {}) => {
    const result = await fetchUsers(page, 20, filters);
    if (result) {
      setUsers(result.users);
      setPagination(result.pagination);
    }
  };

  useEffect(() => {
    loadUsers(1, { search, role, status });
  }, [search, role, status]);

  const handleSuspend = async () => {
    if (!selectedUser || !reason) {
      setLocalError('Please enter a reason');
      return;
    }
    setLocalError(null);
    const result = await suspendUser(selectedUser._id, reason);
    if (result) {
      setSuccessMessage(`User ${selectedUser.email} suspended`);
      setModalActive(false);
      setReason('');
      loadUsers(currentPage, { search, role, status });
      setTimeout(() => setSuccessMessage(''), 3000);
    }
  };

  const handleUnsuspend = async () => {
    if (!selectedUser) return;
    
    const result = await unsuspendUser(selectedUser._id);
    if (result) {
      setSuccessMessage(`User ${selectedUser.email} unsuspended`);
      setModalActive(false);
      loadUsers(currentPage, { search, role, status });
      setTimeout(() => setSuccessMessage(''), 3000);
    }
  };

  const handleDelete = () => {
    if (!selectedUser || !reason) {
      setLocalError('Please enter a reason');
      return;
    }

    setConfirm({
      open: true,
      title: 'Delete User',
      message: 'Are you sure? This action cannot be undone.',
      onConfirm: async () => {
        setConfirm({ open: false });
        setLocalError(null);
        const result = await deleteUser(selectedUser._id, reason);
        if (result) {
          setSuccessMessage(`User ${selectedUser.email} deleted`);
          setModalActive(false);
          setReason('');
          loadUsers(1, { search, role, status });
          setTimeout(() => setSuccessMessage(''), 3000);
        }
      },
    });
  };

  const openModal = (user, type) => {
    setSelectedUser(user);
    setActionType(type);
    setReason('');
    setModalActive(true);
  };

  const closeModal = () => {
    setModalActive(false);
    setSelectedUser(null);
    setActionType(null);
    setReason('');
  };

  // New handler for different action types from UserDetailsModal
  const handleModalAction = (action, user) => {
    if (action === 'suspend') {
      openModal(user, 'suspend');
    } else if (action === 'unsuspend') {
      openModal(user, 'unsuspend');
    } else if (action === 'delete') {
      openModal(user, 'delete');
    } else if (action === 'message') {
      setMessageUser(user);
      setMessageModalOpen(true);
    }
    setDetailsModalOpen(false);
  };

  const openDetailsModal = (user) => {
    setDetailsUser(user);
    setDetailsModalOpen(true);
  };

  if (loading) {
    return (
      <AdminLayout>
        <div className="loading">
          <div className="loading-spinner"></div>
          <p>Loading users...</p>
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="admin-page">
        <h1>User Management</h1>

        {localError && (
          <MessageBanner
            type="error"
            title="Action required"
            message={localError}
            onClose={() => setLocalError(null)}
          />
        )}
        {error && (
          <MessageBanner
            type="error"
            title="Failed to manage users"
            message={error}
            onClose={() => {}}
          />
        )}
        {successMessage && (
          <MessageBanner
            type="success"
            title="Success"
            message={successMessage}
            onClose={() => setSuccessMessage('')}
          />
        )}

        <ConfirmDialog
          open={confirm.open}
          title={confirm.title}
          message={confirm.message}
          onConfirm={confirm.onConfirm}
          onCancel={() => setConfirm({ open: false })}
        />

        {/* Filters */}
        <div className="search-bar">
          <input
            type="text"
            placeholder="Search by email or name..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="search-input"
          />
          <select value={role} onChange={(e) => setRole(e.target.value)} className="search-input">
            <option value="">All Roles</option>
            <option value="student">Students</option>
            <option value="host">Hosts</option>
          </select>
          <select value={status} onChange={(e) => setStatus(e.target.value)} className="search-input">
            <option value="">All Status</option>
            <option value="active">Active</option>
            <option value="suspended">Suspended</option>
            <option value="banned">Banned</option>
          </select>
        </div>

        {/* Users Table */}
        <div className="admin-table">
          <table>
            <thead>
              <tr>
                <th>Email</th>
                <th>Name</th>
                <th>Role</th>
                <th>Status</th>
                <th>Joined</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr key={user._id}>
                  <td>{user.email}</td>
                  <td>{`${user.firstName || ''} ${user.lastName || ''}`.trim() || 'N/A'}</td>
                  <td>
                    {user.isHost && <span className="status-badge active">Host</span>}
                    {user.isStudent && <span className="status-badge pending">Student</span>}
                  </td>
                  <td>
                    {user.bannedAt ? (
                      <span className="status-badge banned">Banned</span>
                    ) : user.suspendedAt ? (
                      <span className="status-badge suspended">Suspended</span>
                    ) : (
                      <span className="status-badge active">Active</span>
                    )}
                  </td>
                  <td>{new Date(user.createdAt).toLocaleDateString()}</td>
                  <td>
                    <button
                      className="btn btn-info btn-sm"
                      onClick={() => openDetailsModal(user)}
                      title="View details and activity"
                    >
                      Details
                    </button>
                    {user.suspendedAt ? (
                      <button
                        className="btn btn-success btn-sm"
                        onClick={() => openModal(user, 'unsuspend')}
                      >
                        Unsuspend
                      </button>
                    ) : (
                      <button
                        className="btn btn-primary btn-sm"
                        onClick={() => openModal(user, 'suspend')}
                      >
                        Suspend
                      </button>
                    )}
                    {!user.bannedAt && (
                      <button
                        className="btn btn-danger btn-sm"
                        onClick={() => openModal(user, 'delete')}
                      >
                        Delete
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {pagination.pages > 1 && (
          <div className="pagination">
            {Array.from({ length: pagination.pages }, (_, i) => i + 1).map((page) => (
              <button
                key={page}
                className={page === currentPage ? 'active' : ''}
                onClick={() => {
                  setCurrentPage(page);
                  loadUsers(page, { search, role, status });
                }}
              >
                {page}
              </button>
            ))}
          </div>
        )}

        {/* Action Modal */}
        <div className={`modal ${modalActive ? 'active' : ''}`}>
          <div className="modal-content">
            <div className="modal-header">
              {actionType === 'suspend' && `Suspend User - ${selectedUser?.email}`}
              {actionType === 'unsuspend' && `Unsuspend User - ${selectedUser?.email}`}
              {actionType === 'delete' && `Delete User - ${selectedUser?.email}`}
            </div>
            <div className="modal-body">
              {(actionType === 'suspend' || actionType === 'delete') && (
                <div className="form-group">
                  <label>Reason</label>
                  <textarea
                    value={reason}
                    onChange={(e) => setReason(e.target.value)}
                    placeholder="Enter reason for this action..."
                  />
                </div>
              )}
              {actionType === 'unsuspend' && (
                <p>Are you sure you want to unsuspend this user? They will regain access to their account.</p>
              )}
            </div>
            <div className="modal-footer">
              <button className="btn" onClick={closeModal}>
                Cancel
              </button>
              {actionType === 'suspend' && (
                <button className="btn btn-warning" onClick={handleSuspend}>
                  Suspend User
                </button>
              )}
              {actionType === 'unsuspend' && (
                <button className="btn btn-success" onClick={handleUnsuspend}>
                  Unsuspend User
                </button>
              )}
              {actionType === 'delete' && (
                <button className="btn btn-danger" onClick={handleDelete}>
                  Delete User
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Phase 5C: User Details Modal */}
        <UserDetailsModal
          user={detailsUser}
          isOpen={detailsModalOpen}
          onClose={() => setDetailsModalOpen(false)}
          onAction={handleModalAction}
        />

        {/* Phase 5C: Admin Message Modal */}
        <AdminMessageModal
          user={messageUser}
          isOpen={messageModalOpen}
          onClose={() => setMessageModalOpen(false)}
          onSuccess={() => {
            setSuccessMessage('Message sent successfully!');
            setTimeout(() => setSuccessMessage(''), 3000);
          }}
        />
      </div>
    </AdminLayout>
  );
};

import React, { useState, useEffect } from 'react';
import { api } from '../utils/api';
import '/Users/abdul/Desktop/class/frontend/src/styles/BundleCreation.css';

export default function BundleCreation() {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    category: '',
    classes: [],
    pricing: {
      discountType: 'percentage', // 'percentage' or 'fixed'
      discountValue: 10
    },
    settings: {
      maxEnrollments: '',
      isActive: true
    }
  });

  const [dynamicPricing, setDynamicPricing] = useState({
    enableDemandPricing: false,
    enableSeasonalPricing: false,
    demandThresholds: [
      { percentage: 50, multiplier: 1.1 },
      { percentage: 75, multiplier: 1.2 },
      { percentage: 90, multiplier: 1.3 }
    ],
    seasonalConfig: [
      { name: 'Winter Sale', months: [11, 0, 1], multiplier: 0.9 },
      { name: 'Summer Promotion', months: [5, 6, 7], multiplier: 0.95 }
    ]
  });

  useEffect(() => {
    fetchHostClasses();
  }, []);

  const fetchHostClasses = async () => {
    try {
      const response = await api.get('/classes/my-classes');
      setAvailableClasses(response.data);
    } catch (err) {
      console.error('Fetch classes error:', err);
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handlePricingChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      pricing: {
        ...prev.pricing,
        [name]: value
      }
    }));
  };

  const handleDynamicPricingChange = (field, value) => {
    setDynamicPricing(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const updateDemandThreshold = (index, field, value) => {
    setDynamicPricing(prev => ({
      ...prev,
      demandThresholds: prev.demandThresholds.map((threshold, i) =>
        i === index ? { ...threshold, [field]: parseFloat(value) } : threshold
      )
    }));
  };

  const updateSeasonalConfig = (index, field, value) => {
    setDynamicPricing(prev => ({
      ...prev,
      seasonalConfig: prev.seasonalConfig.map((season, i) =>
        i === index ? { ...season, [field]: field === 'months' ? value.map(Number) : parseFloat(value) } : season
      )
    }));
  };

  const handleClassToggle = (classId) => {
    setFormData(prev => ({
      ...prev,
      classes: prev.classes.includes(classId)
        ? prev.classes.filter(id => id !== classId)
        : [...prev.classes, classId]
    }));
  };

  const calculateBundlePricing = () => {
    const selectedClasses = availableClasses.filter(cls =>
      formData.classes.includes(cls._id)
    );

    const totalOriginalPrice = selectedClasses.reduce((sum, cls) =>
      sum + (cls.monthlyPrice ?? 0), 0
    );

    let totalBundlePrice = totalOriginalPrice;
    if (formData.pricing.discountType === 'percentage') {
      const discount = totalOriginalPrice * (formData.pricing.discountValue / 100);
      totalBundlePrice = totalOriginalPrice - discount;
    } else {
      totalBundlePrice = Math.max(0, totalOriginalPrice - formData.pricing.discountValue);
    }

    return {
      totalOriginalPrice,
      totalBundlePrice,
      savings: totalOriginalPrice - totalBundlePrice
    };
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      // Validate form
      if (!formData.title.trim()) {
        throw new Error('Bundle title is required');
      }
      if (!formData.description.trim()) {
        throw new Error('Bundle description is required');
      }
      if (!formData.category) {
        throw new Error('Category is required');
      }
      if (formData.classes.length < 2) {
        throw new Error('At least 2 classes must be selected');
      }

      const calculatedPricing = calculateBundlePricing();
      const bundleData = {
        title: formData.title,
        description: formData.description,
        category: formData.category,
        classIds: formData.classes,
        settings: {
          ...formData.settings,
          category: formData.category,
          validFrom: new Date(),
          validUntil: formData.settings.validUntil || null,
        },
        pricing: {
          ...formData.pricing,
          ...calculatedPricing,
          discountPercentage:
            formData.pricing.discountType === 'percentage'
              ? formData.pricing.discountValue
              : formData.pricing.discountValue && calculatedPricing.totalOriginalPrice > 0
                ? Math.round((formData.pricing.discountValue / calculatedPricing.totalOriginalPrice) * 100)
                : 0,
          dynamicRules: {
            timeBasedDiscounts: [],
            demandBasedPricing: {
              enabled: dynamicPricing.enableDemandPricing,
              priceIncreaseThresholds: dynamicPricing.demandThresholds.map(t => ({
                enrollmentPercentage: t.percentage,
                priceMultiplier: t.multiplier
              }))
            },
            seasonalPricing: {
              enabled: dynamicPricing.enableSeasonalPricing,
              seasonalMultipliers: dynamicPricing.seasonalConfig
            },
            lastPriceUpdate: new Date()
          }
        }
      };

      await api.post('/bundles', bundleData);
      setSuccess(true);

      // Reset form
      setFormData({
        title: '',
        description: '',
        category: '',
        classes: [],
        pricing: {
          discountType: 'percentage',
          discountValue: 10
        },
        settings: {
          maxEnrollments: '',
          isActive: true
        }
      });
    } catch (err) {
      setError(err.response?.data?.message || err.message);
    } finally {
      setLoading(false);
    }
  };

  const pricing = calculateBundlePricing();
  const categories = [
    'Technology', 'Business', 'Design', 'Marketing',
    'Language', 'Science', 'Arts', 'Health & Fitness', 'Other'
  ];

  return (
    <div className="bundle-creation">
      <div className="creation-header">
        <h1>Create Course Bundle</h1>
        <p>Combine multiple courses into a discounted bundle to increase sales</p>
      </div>

      {success && (
        <div className="success-message">
          Bundle created successfully! It will be available for students to purchase.
        </div>
      )}

      {error && (
        <div className="error-message">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="bundle-form">
        <div className="form-section">
          <h2>Basic Information</h2>

          <div className="form-group">
            <label htmlFor="title">Bundle Title *</label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleInputChange}
              placeholder="e.g., Complete Web Development Bootcamp"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="description">Description *</label>
            <textarea
              id="description"
              name="description"
              value={formData.description}
              onChange={handleInputChange}
              placeholder="Describe what students will learn from this bundle..."
              rows={4}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="category">Category *</label>
            <select
              id="category"
              name="category"
              value={formData.category}
              onChange={handleInputChange}
              required
            >
              <option value="">Select a category</option>
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="form-section">
          <h2>Select Classes</h2>
          <p>Choose at least 2 classes to include in this bundle</p>

          {availableClasses.length === 0 ? (
            <div className="no-classes">
              <p>You haven't created any classes yet.</p>
              <a href="/create-class" className="create-class-link">
                Create your first class
              </a>
            </div>
          ) : (
            <div className="classes-selection">
              {availableClasses.map(cls => (
                <div key={cls._id} className="class-option">
                  <label className="class-checkbox">
                    <input
                      type="checkbox"
                      checked={formData.classes.includes(cls._id)}
                      onChange={() => handleClassToggle(cls._id)}
                    />
                    <div className="class-info">
                      <div className="class-name">{cls.title}</div>
                      <div className="class-price">${cls.pricing.basePrice}</div>
                      <div className="class-category">{cls.category}</div>
                    </div>
                  </label>
                </div>
              ))}
            </div>
          )}

          {formData.classes.length > 0 && (
            <div className="selected-count">
              {formData.classes.length} class(es) selected
            </div>
          )}
        </div>

        <div className="form-section">
          <h2>Pricing</h2>

          <div className="pricing-options">
            <div className="form-group">
              <label htmlFor="discountType">Discount Type</label>
              <select
                id="discountType"
                name="discountType"
                value={formData.pricing.discountType}
                onChange={handlePricingChange}
              >
                <option value="percentage">Percentage Discount</option>
                <option value="fixed">Fixed Amount Discount</option>
              </select>
            </div>

            <div className="form-group">
              <label htmlFor="discountValue">
                {formData.pricing.discountType === 'percentage' ? 'Discount %' : 'Discount Amount ($)'}
              </label>
              <input
                type="number"
                id="discountValue"
                name="discountValue"
                value={formData.pricing.discountValue}
                onChange={handlePricingChange}
                min="0"
                step={formData.pricing.discountType === 'percentage' ? '1' : '0.01'}
                max={formData.pricing.discountType === 'percentage' ? '100' : pricing.totalOriginalPrice}
              />
            </div>
          </div>

          {formData.classes.length >= 2 && (
            <div className="pricing-preview">
              <h3>Pricing Preview</h3>
              <div className="pricing-details">
                <div className="pricing-row">
                  <span>Individual Price:</span>
                  <span>${pricing.totalOriginalPrice.toFixed(2)}</span>
                </div>
                <div className="pricing-row">
                  <span>Bundle Price:</span>
                  <span>${pricing.totalBundlePrice.toFixed(2)}</span>
                </div>
                <div className="pricing-row savings">
                  <span>You Save:</span>
                  <span>${pricing.savings.toFixed(2)}</span>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="form-section">
          <h2>Settings</h2>

          <div className="form-group">
            <label htmlFor="maxEnrollments">Maximum Enrollments (optional)</label>
            <input
              type="number"
              id="maxEnrollments"
              name="maxEnrollments"
              value={formData.settings.maxEnrollments}
              onChange={handleSettingsChange}
              placeholder="Leave empty for unlimited"
              min="1"
            />
          </div>

          <div className="form-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                name="isActive"
                checked={formData.settings.isActive}
                onChange={handleSettingsChange}
              />
              Make bundle active immediately
            </label>
          </div>
        </div>

        <div className="form-section">
          <h2>Dynamic Pricing (Optional)</h2>
          <p className="section-description">
            Configure advanced pricing strategies that can automatically adjust bundle prices based on demand, seasons, or time-based rules.
          </p>

          <div className="form-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={dynamicPricing.enableDemandPricing}
                onChange={(e) => handleDynamicPricingChange('enableDemandPricing', e.target.checked)}
              />
              Enable demand-based pricing
            </label>
            <small className="help-text">
              Automatically increase prices as enrollment fills up to create urgency
            </small>
          </div>

          {dynamicPricing.enableDemandPricing && (
            <div className="dynamic-pricing-config">
              <h3>Demand Thresholds</h3>
              <div className="thresholds-list">
                {dynamicPricing.demandThresholds.map((threshold, index) => (
                  <div key={index} className="threshold-item">
                    <div className="threshold-inputs">
                      <div className="form-group">
                        <label>Enrollment %</label>
                        <input
                          type="number"
                          value={threshold.percentage}
                          onChange={(e) => updateDemandThreshold(index, 'percentage', e.target.value)}
                          min="1"
                          max="100"
                        />
                      </div>
                      <div className="form-group">
                        <label>Price Multiplier</label>
                        <input
                          type="number"
                          value={threshold.multiplier}
                          onChange={(e) => updateDemandThreshold(index, 'multiplier', e.target.value)}
                          step="0.1"
                          min="1"
                        />
                      </div>
                    </div>
                    <small className="threshold-preview">
                      When {threshold.percentage}% enrolled, price becomes {threshold.multiplier}x base price
                    </small>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="form-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={dynamicPricing.enableSeasonalPricing}
                onChange={(e) => handleDynamicPricingChange('enableSeasonalPricing', e.target.checked)}
              />
              Enable seasonal pricing
            </label>
            <small className="help-text">
              Apply different pricing during specific months or seasons
            </small>
          </div>

          {dynamicPricing.enableSeasonalPricing && (
            <div className="dynamic-pricing-config">
              <h3>Seasonal Configurations</h3>
              <div className="seasons-list">
                {dynamicPricing.seasonalConfig.map((season, index) => (
                  <div key={index} className="season-item">
                    <div className="season-inputs">
                      <div className="form-group">
                        <label>Season Name</label>
                        <input
                          type="text"
                          value={season.name}
                          onChange={(e) => updateSeasonalConfig(index, 'name', e.target.value)}
                          placeholder="e.g., Holiday Sale"
                        />
                      </div>
                      <div className="form-group">
                        <label>Months (0-11)</label>
                        <input
                          type="text"
                          value={season.months.join(', ')}
                          onChange={(e) => updateSeasonalConfig(index, 'months', e.target.value.split(',').map(s => s.trim()))}
                          placeholder="e.g., 11, 0, 1"
                        />
                      </div>
                      <div className="form-group">
                        <label>Price Multiplier</label>
                        <input
                          type="number"
                          value={season.multiplier}
                          onChange={(e) => updateSeasonalConfig(index, 'multiplier', e.target.value)}
                          step="0.1"
                          min="0.1"
                        />
                      </div>
                    </div>
                    <small className="season-preview">
                      During {season.name}: price becomes {season.multiplier}x base price
                    </small>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="pricing-note">
            <p><strong>Note:</strong> You can configure additional dynamic pricing strategies (flash sales, time-based discounts, A/B testing) after creating the bundle using the Dynamic Pricing Manager.</p>
          </div>
        </div>

        <div className="form-actions">
          <button
            type="submit"
            className="btn btn-primary"
            disabled={loading || formData.classes.length < 2}
          >
            {loading ? 'Creating Bundle...' : 'Create Bundle'}
          </button>
        </div>
      </form>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useAuth } from '../hooks/useAuth';
import { Navigate, Link } from 'react-router-dom';
import api from '../utils/api';
import '../styles/Dashboard.css';

export default function DashboardPage() {
  const { user, isAuthenticated, loading } = useAuth();
  const [points, setPoints] = useState(null);

  useEffect(() => {
    let mounted = true;
    async function loadPoints() {
      if (!user) return;
      try {
        const res = await api.get(`/points/balance/${user._id}`);
        if (mounted) setPoints(res.data.balance || 0);
      } catch (err) {
        console.warn('Failed to load points balance', err.message || err);
      }
    }
    loadPoints();
    return () => { mounted = false; };
  }, [user]);

  if (loading) {
    return <div className="loading">Loading...</div>;
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className="dashboard-page">
      <div className="container">
        <h1>My Learning Dashboard</h1>

        <div className="dashboard-grid">
          <section className="dashboard-card">
            <h2>My Profile</h2>
            <div className="profile-info">
              <p>
                <strong>Name:</strong> {user?.firstName} {user?.lastName}
              </p>
              <p>
                <strong>Email:</strong> {user?.email}
              </p>
              <p>
                <strong>Member Since:</strong>{' '}
                {user?.createdAt ? new Date(user.createdAt).toLocaleDateString() : 'N/A'}
              </p>
              <p>
                <strong>Points:</strong> {points != null ? points : '—'} (<Link to="/points">View history</Link>)
              </p>
            </div>
          </section>

          <section className="dashboard-card">
            <h2>My Enrollments</h2>
            <p>You haven't enrolled in any classes yet.</p>
            <Link to="/browse" className="btn btn-primary">
              Browse Classes
            </Link>
          </section>

          <section className="dashboard-card">
            <h2>Payment History</h2>
            <p>No payments yet.</p>
          </section>

          <section className="dashboard-card">
            <h2>Progress Tracking</h2>
            <p>Track your attendance, completion percentage, and achievements here.</p>
          </section>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { api } from '../utils/api';
import DiscountAnalyticsDashboard from '../components/DiscountAnalyticsDashboard';
import ConfirmDialog from '../components/ConfirmDialog';
import MessageBanner from '../components/MessageBanner';
import '../styles/DiscountManager.css';

export default function DiscountManager() {
  const [discounts, setDiscounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [editingDiscount, setEditingDiscount] = useState(null);
  const [viewMode, setViewMode] = useState('list');
  const [selectedDiscount, setSelectedDiscount] = useState(null);

  const initialFormState = {
    code: '',
    name: '',
    description: '',
    type: 'percentage',
    value: 10,
    conditions: {
      minPurchase: 0,
      maxUses: '',
      validFrom: '',
      validUntil: '',
      applicableTo: 'all',
      specificItems: [],
      userRestrictions: {
        firstTimeOnly: false,
        maxUsesPerUser: ''
      }
    }
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    fetchDiscounts();
  }, []);

  // FETCH DISCOUNTS
  const fetchDiscounts = async () => {
    try {
      setLoading(true);

      const response = await api.get('/discounts');

      setDiscounts(response.data?.discounts || []);
    } catch (err) {
      setError('Failed to load discounts');
      console.error('Fetch discounts error:', err);
    } finally {
      setLoading(false);
    }
  };

  // RESET FORM
  const resetForm = () => {
    setFormData(initialFormState);
    setEditingDiscount(null);
    setShowCreateForm(false);
    setError(null);
  };

  // INPUT CHANGES
  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  // CONDITIONS CHANGES
  const handleConditionsChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData((prev) => ({
      ...prev,
      conditions: {
        ...prev.conditions,
        [name]: type === 'checkbox' ? checked : value
      }
    }));
  };

  // USER RESTRICTIONS CHANGES
  const handleUserRestrictionsChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData((prev) => ({
      ...prev,
      conditions: {
        ...prev.conditions,
        userRestrictions: {
          ...prev.conditions.userRestrictions,
          [name]: type === 'checkbox' ? checked : value
        }
      }
    }));
  };

  // SUBMIT FORM
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      setLoading(true);
      setError(null);

      const discountData = {
        ...formData,
        code: formData.code.toUpperCase(),
        value: Number(formData.value),

        conditions: {
          ...formData.conditions,

          minPurchase:
            parseFloat(formData.conditions.minPurchase) || 0,

          maxUses: formData.conditions.maxUses
            ? parseInt(formData.conditions.maxUses)
            : undefined,

          validFrom:
            formData.conditions.validFrom ||
            new Date().toISOString(),

          validUntil:
            formData.conditions.validUntil || undefined,

          userRestrictions: {
            ...formData.conditions.userRestrictions,

            maxUsesPerUser:
              formData.conditions.userRestrictions.maxUsesPerUser
                ? parseInt(
                    formData.conditions.userRestrictions
                      .maxUsesPerUser
                  )
                : undefined
          }
        }
      };

      // UPDATE
      if (editingDiscount) {
        await api.put(
          `/discounts/${editingDiscount._id}`,
          discountData
        );
      }

      // CREATE
      else {
        await api.post('/discounts', discountData);
      }

      resetForm();
      fetchDiscounts();
    } catch (err) {
      setError(
        err.response?.data?.message ||
          'Failed to save discount'
      );

      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // EDIT DISCOUNT
  const handleEdit = (discount) => {
    setFormData({
      code: discount.code || '',
      name: discount.name || '',
      description: discount.description || '',
      type: discount.type || 'percentage',
      value: discount.value || 0,

      conditions: {
        minPurchase:
          discount.conditions?.minPurchase || 0,

        maxUses:
          discount.conditions?.maxUses || '',

        validFrom: discount.conditions?.validFrom
          ? new Date(discount.conditions.validFrom)
              .toISOString()
              .split('T')[0]
          : '',

        validUntil: discount.conditions?.validUntil
          ? new Date(discount.conditions.validUntil)
              .toISOString()
              .split('T')[0]
          : '',

        applicableTo:
          discount.conditions?.applicableTo || 'all',

        specificItems:
          discount.conditions?.specificItems || [],

        userRestrictions: {
          firstTimeOnly:
            discount.conditions?.userRestrictions
              ?.firstTimeOnly || false,

          maxUsesPerUser:
            discount.conditions?.userRestrictions
              ?.maxUsesPerUser || ''
        }
      }
    });

    setEditingDiscount(discount);
    setShowCreateForm(true);
  };

  // DELETE DISCOUNT
  const [confirm, setConfirm] = useState({ open: false, title: '', message: '', onConfirm: null });

  const handleDelete = (discountId) => {
    setConfirm({
      open: true,
      title: 'Delete Discount',
      message: 'Are you sure you want to delete this discount?',
      onConfirm: async () => {
        setConfirm({ open: false });
        try {
          await api.delete(`/discounts/${discountId}`);
          fetchDiscounts();
        } catch (err) {
          setError('Failed to delete discount');
          console.error(err);
        }
      },
    });
  };

  // TOGGLE STATUS
  const toggleDiscountStatus = async (discount) => {
    try {
      await api.put(`/discounts/${discount._id}`, {
        ...discount,
        isActive: !discount.isActive
      });

      fetchDiscounts();
    } catch (err) {
      setError('Failed to update discount status');

      console.error('Toggle status error:', err);
    }
  };

  // VIEW ANALYTICS
  const handleViewAnalytics = (discount) => {
    setSelectedDiscount(discount);
    setViewMode('analytics');
  };

  // VIEW OVERALL ANALYTICS
  const handleViewOverallAnalytics = () => {
    setSelectedDiscount(null);
    setViewMode('overall');
  };

  // BACK TO LIST
  const handleBackToList = () => {
    setViewMode('list');
    setSelectedDiscount(null);
  };

  // FORMAT DATE
  const formatDate = (dateString) => {
    if (!dateString) return 'No limit';

    return new Date(dateString).toLocaleDateString();
  };

  // STATUS BADGES
  const getStatusBadge = (discount) => {
    if (!discount.isActive) {
      return (
        <span className="status inactive">
          Inactive
        </span>
      );
    }

    if (discount.isExpired) {
      return (
        <span className="status expired">
          Expired
        </span>
      );
    }

    if (!discount.isAvailable) {
      return (
        <span className="status unavailable">
          Unavailable
        </span>
      );
    }

    return (
      <span className="status active">
        Active
      </span>
    );
  };

  // LOADING SCREEN
  if (loading && discounts.length === 0) {
    return (
      <div className="discount-manager">
        <div className="loading">
          Loading discounts...
        </div>
      </div>
    );
  }

  return (
    <div className="discount-manager">
      {error && (
        <MessageBanner type="error" title="Discounts" message={error} onClose={() => setError(null)} />
      )}

      <ConfirmDialog
        open={confirm.open}
        title={confirm.title}
        message={confirm.message}
        onConfirm={confirm.onConfirm}
        onCancel={() => setConfirm({ open: false })}
      />

      {/* HEADER */}
      <div className="manager-header">
        <h1>Discount Code Manager</h1>

        <p>
          Create and manage discount codes
          for your courses and bundles
        </p>

        <div className="header-actions">

          {viewMode !== 'list' && (
            <button
              onClick={handleBackToList}
              className="btn btn-secondary"
            >
              ← Back to List
            </button>
          )}

          {viewMode === 'list' && (
            <>
              <button
                onClick={() =>
                  setShowCreateForm(!showCreateForm)
                }
                className="btn btn-primary"
              >
                {showCreateForm
                  ? 'Cancel'
                  : 'Create New Discount'}
              </button>
              {discounts.length >= 3 && (
                <button
                  onClick={handleViewOverallAnalytics}
                  className="btn btn-info"
                >
                  📊 Overall Analytics
                </button>
              )}
              {discounts.length < 3 && (
                <div className="analytics-note">
                  Create at least 3 discount codes to enable overall analytics for the full set.
                </div>
              )}
            </>
          )}

        </div>
      </div>

      {/* ERROR */}
      {error && (
        <div className="error-message">
          {error}
        </div>
      )}

      {/* ANALYTICS */}
      {viewMode === 'analytics' && selectedDiscount ? (
        <DiscountAnalyticsDashboard
          discountId={selectedDiscount._id}
        />
      ) : viewMode === 'overall' ? (
        <DiscountAnalyticsDashboard overall />
      ) : (
        <>
          {/* FORM */}
          {showCreateForm && (
            <form
              onSubmit={handleSubmit}
              className="discount-form"
            >

              <h2>
                {editingDiscount
                  ? 'Edit Discount'
                  : 'Create New Discount'}
              </h2>

              {/* CODE + NAME */}
              <div className="form-row">

                <div className="form-group">
                  <label>Discount Code *</label>

                  <input
                    type="text"
                    name="code"
                    value={formData.code}
                    onChange={handleInputChange}
                    placeholder="SUMMER2026"
                    required
                    disabled={editingDiscount}
                  />
                </div>

                <div className="form-group">
                  <label>Name *</label>

                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    placeholder="Summer Sale"
                    required
                  />
                </div>

              </div>

              {/* DESCRIPTION */}
              <div className="form-group">
                <label>Description</label>

                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  rows={3}
                />
              </div>

              {/* TYPE + VALUE */}
              <div className="form-row">

                <div className="form-group">
                  <label>Discount Type</label>

                  <select
                    name="type"
                    value={formData.type}
                    onChange={handleInputChange}
                  >
                    <option value="percentage">
                      Percentage
                    </option>

                    <option value="fixed">
                      Fixed Amount
                    </option>
                  </select>
                </div>

                <div className="form-group">
                  <label>
                    {formData.type === 'percentage'
                      ? 'Discount %'
                      : 'Discount Amount ($)'}
                  </label>

                  <input
                    type="number"
                    name="value"
                    value={formData.value}
                    onChange={handleInputChange}
                    min="0"
                    required
                  />
                </div>

              </div>

              {/* ACTION BUTTONS */}
              <div className="form-actions">

                <button
                  type="button"
                  onClick={resetForm}
                  className="btn btn-secondary"
                >
                  Cancel
                </button>

                <button
                  type="submit"
                  className="btn btn-primary"
                  disabled={loading}
                >
                  {loading
                    ? 'Saving...'
                    : editingDiscount
                    ? 'Update Discount'
                    : 'Create Discount'}
                </button>

              </div>

            </form>
          )}

          {/* DISCOUNTS LIST */}
          <div className="discounts-list">

            <h2>Your Discount Codes</h2>

            {discounts.length === 0 ? (
              <div className="no-discounts">

                <p>
                  You haven't created any
                  discount codes yet.
                </p>

                <button
                  onClick={() =>
                    setShowCreateForm(true)
                  }
                  className="btn btn-primary"
                >
                  Create Your First Discount
                </button>

              </div>
            ) : (
              <div className="discounts-grid">
                {discounts.length >= 3 && (
                  <div className="discount-card overall-analytics-card">
                    <div className="discount-header">
                      <div className="discount-code">ALL DISCOUNTS</div>
                      <span className="status active">Overview</span>
                    </div>
                    <div className="discount-content">
                      <h3>Overall Discount Analytics</h3>
                      <p>
                        Review total code usage, revenue impact, and top-performing discounts across your entire account.
                      </p>
                    </div>
                    <div className="discount-actions">
                      <button
                        onClick={handleViewOverallAnalytics}
                        className="btn btn-info"
                      >
                        View Overall Analytics
                      </button>
                    </div>
                  </div>
                )}

                {discounts.map((discount) => (
                  <div
                    key={discount._id}
                    className="discount-card"
                  >

                    {/* HEADER */}
                    <div className="discount-header">

                      <div className="discount-code">
                        {discount.code}
                      </div>

                      {getStatusBadge(discount)}

                    </div>

                    {/* CONTENT */}
                    <div className="discount-content">

                      <h3>{discount.name}</h3>

                      <p>
                        {discount.description ||
                          'No description provided'}
                      </p>

                      <div className="discount-details">

                        <div className="detail-row">
                          <span>Type:</span>

                          <span>
                            {discount.type ===
                            'percentage'
                              ? `${discount.value}% off`
                              : `$${discount.value} off`}
                          </span>
                        </div>

                        <div className="detail-row">
                          <span>Uses:</span>

                          <span>
                            {discount.conditions
                              ?.usageCount || 0}
                          </span>
                        </div>

                        <div className="detail-row">
                          <span>Expires:</span>

                          <span>
                            {formatDate(
                              discount.conditions
                                ?.validUntil
                            )}
                          </span>
                        </div>

                      </div>
                    </div>

                    {/* ACTIONS */}
                    <div className="discount-actions">

                      <button
                        onClick={() =>
                          handleViewAnalytics(
                            discount
                          )
                        }
                        className="btn btn-info"
                      >
                        📊 Analytics
                      </button>

                      <button
                        onClick={() =>
                          toggleDiscountStatus(
                            discount
                          )
                        }
                        className={`btn ${
                          discount.isActive
                            ? 'btn-warning'
                            : 'btn-success'
                        }`}
                      >
                        {discount.isActive
                          ? 'Deactivate'
                          : 'Activate'}
                      </button>

                      <button
                        onClick={() =>
                          handleEdit(discount)
                        }
                        className="btn btn-secondary"
                      >
                        Edit
                      </button>

                      <button
                        onClick={() =>
                          handleDelete(
                            discount._id
                          )
                        }
                        className="btn btn-danger"
                      >
                        Delete
                      </button>

                    </div>

                  </div>
                ))}

              </div>
            )}

          </div>
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '../hooks/useAuth';
import { Navigate } from 'react-router-dom';
import LoadingSpinner from '../components/LoadingSpinner';
import MessageBanner from '../components/MessageBanner';
import ConfirmDialog from '../components/ConfirmDialog';
import api from '../utils/api';
import '../styles/EmailTemplateEditor.css';

const EMAIL_CATEGORIES = [
  'certificate',
  'achievement',
  'progress',
  'enrollment',
  'class',
  'payment',
  'admin',
  'system',
];

export default function EmailTemplateEditor() {
  const { user, isAuthenticated, loading } = useAuth();
  const [templates, setTemplates] = useState([]);
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [isCreating, setIsCreating] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    subject: '',
    htmlContent: '',
    textContent: '',
    category: 'system',
  });
  const [variables, setVariables] = useState([]);
  const [newVariable, setNewVariable] = useState({ name: '', description: '', defaultValue: '' });
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [saving, setSaving] = useState(false);
  const [preview, setPreview] = useState(null);
  const [showPreview, setShowPreview] = useState(false);

  if (loading) {
    return <LoadingSpinner fullPage={true} message="Loading email templates..." />;
  }

  if (!isAuthenticated || !user?.isAdmin) {
    return <Navigate to="/login" replace />;
  }

  useEffect(() => {
    fetchTemplates();
  }, []);

  const fetchTemplates = async () => {
    try {
      const response = await api.get('/email/templates');
      setTemplates(response.data);
    } catch (err) {
      console.error('Error fetching templates:', err);
      setError('Failed to load templates');
    }
  };

  const handleTemplateSelect = (template) => {
    setSelectedTemplate(template);
    setFormData({
      name: template.name,
      description: template.description,
      subject: template.subject,
      htmlContent: template.htmlContent,
      textContent: template.textContent,
      category: template.category,
    });
    setVariables(template.variables || []);
    setIsCreating(false);
    setError(null);
    setSuccess(null);
  };

  const handleNewTemplate = () => {
    setSelectedTemplate(null);
    setFormData({
      name: '',
      description: '',
      subject: '',
      htmlContent: '',
      textContent: '',
      category: 'system',
    });
    setVariables([]);
    setIsCreating(true);
    setError(null);
    setSuccess(null);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleAddVariable = () => {
    if (newVariable.name.trim()) {
      setVariables(prev => [...prev, { ...newVariable }]);
      setNewVariable({ name: '', description: '', defaultValue: '' });
    }
  };

  const handleRemoveVariable = (index) => {
    setVariables(prev => prev.filter((_, i) => i !== index));
  };

  const handlePreview = async () => {
    try {
      setPreview(null);
      const previewData = {};
      variables.forEach(v => {
        previewData[v.name] = v.defaultValue || `[${v.name}]`;
      });

      // Manually interpolate since we're in editing mode
      const subject = interpolate(formData.subject, previewData);
      const htmlContent = interpolate(formData.htmlContent, previewData);

      setPreview({ subject, htmlContent });
      setShowPreview(true);
    } catch (err) {
      setError('Error generating preview');
    }
  };

  const interpolate = (template, variables) => {
    let result = template;
    Object.keys(variables).forEach(key => {
      const regex = new RegExp(`{{${key}}}`, 'g');
      result = result.replace(regex, variables[key] || '');
    });
    return result;
  };

  const handleSave = async () => {
    if (!formData.name.trim()) {
      setError('Template name is required');
      return;
    }

    if (!formData.subject.trim()) {
      setError('Email subject is required');
      return;
    }

    if (!formData.htmlContent.trim()) {
      setError('HTML content is required');
      return;
    }

    setSaving(true);
    setError(null);

    try {
      const payload = {
        ...formData,
        variables,
      };

      if (isCreating) {
        await api.post('/email/templates', payload);
        setSuccess('Template created successfully');
      } else {
        await api.put(`/email/templates/${selectedTemplate._id}`, payload);
        setSuccess('Template updated successfully');
      }

      setTimeout(() => {
        fetchTemplates();
        if (isCreating) {
          handleNewTemplate();
        }
      }, 1000);
    } catch (err) {
      setError(err.response?.data?.message || 'Error saving template');
    } finally {
      setSaving(false);
    }
  };

  const [confirm, setConfirm] = React.useState({ open: false, title: '', message: '', onConfirm: null });

  const handleDelete = () => {
    if (!selectedTemplate) return;

    setConfirm({
      open: true,
      title: 'Delete Template',
      message: 'Are you sure you want to delete this template?',
      onConfirm: async () => {
        setConfirm({ open: false });
        try {
          await api.delete(`/email/templates/${selectedTemplate._id}`);
          setSuccess('Template deleted successfully');
          setTimeout(() => {
            fetchTemplates();
            setSelectedTemplate(null);
          }, 1000);
        } catch (err) {
          setError('Error deleting template');
        }
      },
    });
  };

  return (
    <div className="email-template-editor">
      <div className="container">
        <h1>Email Template Editor</h1>
        <p className="subtitle">Create and manage email templates with variable interpolation</p>

        {error && (
          <MessageBanner
            type="error"
            title="Template save failed"
            message={error}
            onClose={() => setError(null)}
          />
        )}

        {success && (
          <MessageBanner
            type="success"
            title="Template saved"
            message={success}
            onClose={() => setSuccess(null)}
          />
        )}

        <ConfirmDialog
          open={confirm.open}
          title={confirm.title}
          message={confirm.message}
          onConfirm={confirm.onConfirm}
          onCancel={() => setConfirm({ open: false })}
        />

        <div className="editor-layout">
          {/* Template List Sidebar */}
          <aside className="template-list-sidebar">
            <div className="sidebar-header">
              <h2>Templates</h2>
              <button onClick={handleNewTemplate} className="btn btn-primary btn-sm">
                + New Template
              </button>
            </div>

            <div className="template-filters">
              <label>Filter by category:</label>
              <select className="category-filter" defaultValue="">
                <option value="">All Categories</option>
                {EMAIL_CATEGORIES.map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>

            <div className="template-list">
              {templates.length === 0 ? (
                <p className="no-templates">No templates yet</p>
              ) : (
                templates.map(template => (
                  <div
                    key={template._id}
                    className={`template-item ${selectedTemplate?._id === template._id ? 'active' : ''}`}
                    onClick={() => handleTemplateSelect(template)}
                  >
                    <h3>{template.name}</h3>
                    <p className="category-badge">{template.category}</p>
                    <p className="template-preview">{template.subject}</p>
                  </div>
                ))
              )}
            </div>
          </aside>

          {/* Editor Panel */}
          <main className="template-editor">
            {!selectedTemplate && !isCreating ? (
              <div className="no-selection">
                <p>Select a template to edit or create a new one</p>
              </div>
            ) : (
              <div className="editor-form">
                <div className="form-section">
                  <h2>Template Information</h2>

                  <div className="form-group">
                    <label htmlFor="name">Template Name *</label>
                    <input
                      type="text"
                      id="name"
                      name="name"
                      value={formData.name}
                      onChange={handleInputChange}
                      placeholder="e.g., Certificate Issued"
                      disabled={!isCreating && selectedTemplate?.isSystem}
                    />
                  </div>

                  <div className="form-group">
                    <label htmlFor="description">Description</label>
                    <input
                      type="text"
                      id="description"
                      name="description"
                      value={formData.description}
                      onChange={handleInputChange}
                      placeholder="What is this template for?"
                      disabled={!isCreating && selectedTemplate?.isSystem}
                    />
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label htmlFor="category">Category</label>
                      <select
                        id="category"
                        name="category"
                        value={formData.category}
                        onChange={handleInputChange}
                        disabled={!isCreating && selectedTemplate?.isSystem}
                      >
                        {EMAIL_CATEGORIES.map(cat => (
                          <option key={cat} value={cat}>{cat}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>

                {/* Email Content */}
                <div className="form-section">
                  <h2>Email Content</h2>

                  <div className="form-group">
                    <label htmlFor="subject">Email Subject *</label>
                    <input
                      type="text"
                      id="subject"
                      name="subject"
                      value={formData.subject}
                      onChange={handleInputChange}
                      placeholder="e.g., Your certificate is ready - {{courseName}}"
                      disabled={!isCreating && selectedTemplate?.isSystem}
                    />
                    <small>Use {{variable}} syntax for dynamic content</small>
                  </div>

                  <div className="form-group">
                    <label htmlFor="htmlContent">HTML Content *</label>
                    <textarea
                      id="htmlContent"
                      name="htmlContent"
                      value={formData.htmlContent}
                      onChange={handleInputChange}
                      placeholder="<h1>Congratulations!</h1><p>You have completed {{courseName}}</p>"
                      rows={12}
                      disabled={!isCreating && selectedTemplate?.isSystem}
                    />
                    <small>Full HTML is supported. Use {{variable}} for dynamic content.</small>
                  </div>

                  <div className="form-group">
                    <label htmlFor="textContent">Text Content</label>
                    <textarea
                      id="textContent"
                      name="textContent"
                      value={formData.textContent}
                      onChange={handleInputChange}
                      placeholder="Plain text version (optional)"
                      rows={8}
                      disabled={!isCreating && selectedTemplate?.isSystem}
                    />
                    <small>Plain text version for clients that don't support HTML</small>
                  </div>
                </div>

                {/* Variables */}
                <div className="form-section">
                  <h2>Template Variables</h2>
                  <p className="section-help">Define variables that can be used in the template</p>

                  <div className="variables-list">
                    {variables.length === 0 ? (
                      <p className="no-variables">No variables yet</p>
                    ) : (
                      variables.map((v, idx) => (
                        <div key={idx} className="variable-item">
                          <div className="variable-info">
                            <strong>{`{{${v.name}}}`}</strong>
                            {v.description && <span>{v.description}</span>}
                            {v.defaultValue && <span className="default">Default: {v.defaultValue}</span>}
                          </div>
                          <button
                            type="button"
                            onClick={() => handleRemoveVariable(idx)}
                            className="btn-remove"
                          >
                            Remove
                          </button>
                        </div>
                      ))
                    )}
                  </div>

                  <div className="add-variable-form">
                    <input
                      type="text"
                      value={newVariable.name}
                      onChange={(e) => setNewVariable(prev => ({ ...prev, name: e.target.value }))}
                      placeholder="Variable name (e.g., studentName)"
                    />
                    <input
                      type="text"
                      value={newVariable.description}
                      onChange={(e) => setNewVariable(prev => ({ ...prev, description: e.target.value }))}
                      placeholder="Description (optional)"
                    />
                    <input
                      type="text"
                      value={newVariable.defaultValue}
                      onChange={(e) => setNewVariable(prev => ({ ...prev, defaultValue: e.target.value }))}
                      placeholder="Default value (optional)"
                    />
                    <button
                      type="button"
                      onClick={handleAddVariable}
                      className="btn btn-secondary"
                    >
                      Add Variable
                    </button>
                  </div>
                </div>

                {/* Actions */}
                <div className="form-actions">
                  <button
                    onClick={handlePreview}
                    className="btn btn-secondary"
                  >
                    📧 Preview
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={saving}
                    className="btn btn-primary"
                  >
                    {saving ? 'Saving...' : (isCreating ? 'Create Template' : 'Save Changes')}
                  </button>
                  {selectedTemplate && !selectedTemplate.isSystem && (
                    <button
                      onClick={handleDelete}
                      className="btn btn-danger"
                    >
                      🗑️ Delete
                    </button>
                  )}
                </div>
              </div>
            )}
          </main>
        </div>

        {/* Preview Modal */}
        {showPreview && preview && (
          <div className="preview-modal" onClick={() => setShowPreview(false)}>
            <div className="preview-content" onClick={(e) => e.stopPropagation()}>
              <div className="preview-header">
                <h2>Email Preview</h2>
                <button onClick={() => setShowPreview(false)} className="close-btn">×</button>
              </div>

              <div className="preview-body">
                <div className="preview-section">
                  <h3>Subject:</h3>
                  <p className="subject-preview">{preview.subject}</p>
                </div>

                <div className="preview-section">
                  <h3>Email Body:</h3>
                  <iframe
                    srcDoc={`<div style="font-family: Arial, sans-serif; padding: 20px;">${preview.htmlContent}</div>`}
                    style={{ width: '100%', height: '400px', border: 'none', borderRadius: '8px' }}
                  />
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import api from '../utils/api';
import { loadStripe } from '@stripe/stripe-js';
import useEventLogger from '../hooks/useEventLogger';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import '../styles/Enrollment.css';

const stripePromise = loadStripe(import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY || 'pk_test_example');

function EnrollmentForm({ classData, selectedDays, onSuccess }) {
  const stripe = useStripe();
  const elements = useElements();
  const [discountCode, setDiscountCode] = useState('');
  const [discountValidation, setDiscountValidation] = useState(null);
  const [isValidating, setIsValidating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState('');

  const calculatePrice = () => {
    const baseRate = classData.monthlyPrice / 30;
    let multiplier = 1.0;

    if (selectedDays >= 1 && selectedDays <= 3) multiplier = 1.8;
    else if (selectedDays >= 4 && selectedDays <= 6) multiplier = 1.5;
    else if (selectedDays >= 7 && selectedDays <= 13) multiplier = 1.25;
    else if (selectedDays >= 14 && selectedDays <= 20) multiplier = 1.1;

    return Math.round(baseRate * multiplier * selectedDays * 100) / 100;
  };

  const originalPrice = calculatePrice();
  const discountAmount = discountValidation?.valid ? discountValidation.discount.discountAmount : 0;
  const finalPrice = Math.max(0, originalPrice - discountAmount);

  const validateDiscount = async () => {
    if (!discountCode.trim()) {
      setDiscountValidation(null);
      return;
    }

    setIsValidating(true);
    setError('');

    try {
      const response = await api.post('/discounts/validate', {
        code: discountCode,
        itemId: classData._id,
        itemType: 'Class',
        purchaseAmount: originalPrice
      });

      setDiscountValidation(response.data);
    } catch (err) {
      setDiscountValidation({
        valid: false,
        reason: err.response?.data?.message || 'Invalid discount code'
      });
    } finally {
      setIsValidating(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!stripe || !elements) {
      setError('Stripe not loaded');
      return;
    }

    setIsProcessing(true);
    setError('');

    try {
      // Create payment intent
      const paymentResponse = await api.post('/payments/create-intent', {
        classId: classData._id,
        numberOfDays: selectedDays,
        discountCode: discountValidation?.valid ? discountCode : null
      });

      const { clientSecret } = paymentResponse.data;

      // Confirm payment
      const { error: stripeError } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: {
          card: elements.getElement(CardElement),
        }
      });

      if (stripeError) {
        setError(stripeError.message);
        return;
      }

      // Confirm payment on backend
      await api.post('/payments/confirm', {
        paymentIntentId: paymentResponse.data.clientSecret.split('_secret_')[0],
        classId: classData._id,
        numberOfDays: selectedDays
      });

      onSuccess();
    } catch (err) {
      setError(err.response?.data?.message || 'Payment failed');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="enrollment-form">
      <div className="price-summary">
        <h3>Order Summary</h3>
        <div className="price-breakdown">
          <div className="price-row">
            <span>{selectedDays} days × ${classData.monthlyPrice}/month</span>
            <span>${originalPrice.toFixed(2)}</span>
          </div>
          {discountValidation?.valid && (
            <div className="price-row discount">
              <span>Discount ({discountValidation.discount.name})</span>
              <span>-${discountAmount.toFixed(2)}</span>
            </div>
          )}
          <div className="price-row total">
            <span>Total</span>
            <span>${finalPrice.toFixed(2)}</span>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Discount Code (Optional)</label>
          <div className="discount-input-group">
            <input
              type="text"
              value={discountCode}
              onChange={(e) => setDiscountCode(e.target.value.toUpperCase())}
              placeholder="Enter discount code"
              className="discount-input"
            />
            <button
              type="button"
              onClick={validateDiscount}
              disabled={isValidating || !discountCode.trim()}
              className="btn btn-secondary"
            >
              {isValidating ? 'Validating...' : 'Apply'}
            </button>
          </div>

          {discountValidation && (
            <div className={`discount-message ${discountValidation.valid ? 'success' : 'error'}`}>
              {discountValidation.valid ? (
                <>
                  <p>✅ {discountValidation.discount.name} applied!</p>
                  <p>You save ${discountAmount.toFixed(2)}</p>
                  {discountValidation.remainingTotalUses !== null && (
                    <p>{discountValidation.remainingTotalUses} uses remaining</p>
                  )}
                  {discountValidation.remainingUserUses !== null && (
                    <p>{discountValidation.remainingUserUses} uses left for you</p>
                  )}
                </>
              ) : (
                <p>❌ {discountValidation.reason}</p>
              )}
            </div>
          )}
        </div>

        <div className="form-group">
          <label>Payment Information</label>
          <div className="card-element-wrapper">
            <CardElement
              options={{
                style: {
                  base: {
                    fontSize: '16px',
                    color: '#424770',
                    '::placeholder': {
                      color: '#aab7c4',
                    },
                  },
                  invalid: {
                    color: '#9e2146',
                  },
                },
              }}
            />
          </div>
        </div>

        {error && <div className="error-message">{error}</div>}

        <button
          type="submit"
          disabled={!stripe || isProcessing}
          className="btn btn-primary full-width"
        >
          {isProcessing ? 'Processing...' : `Pay $${finalPrice.toFixed(2)}`}
        </button>
      </form>
    </div>
  );
}

export default function EnrollmentPage() {
  const { classId } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();

  const [classData, setClassData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedDays, setSelectedDays] = useState(1);
  const [enrolled, setEnrolled] = useState(false);

  const { logEvent } = useEventLogger();

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }

    const days = parseInt(searchParams.get('days')) || 1;
    setSelectedDays(Math.max(1, Math.min(30, days)));

    fetchClass();
  }, [classId, isAuthenticated, navigate, searchParams]);

  useEffect(() => {
    if (classData) {
      logEvent({ action: 'view_enrollment', targetType: 'class', targetId: classData._id });
    }
  }, [classData]);

  const fetchClass = async () => {
    try {
      const response = await api.get(`/classes/${classId}`);
      setClassData(response.data);
    } catch (error) {
      console.error('Failed to fetch class:', error);
      navigate('/browse');
    } finally {
      setLoading(false);
    }
  };

  const handleEnrollmentSuccess = () => {
    setEnrolled(true);
    setTimeout(() => {
      navigate('/dashboard');
    }, 3000);
  };

  if (loading) {
    return <div className="loading">Loading enrollment...</div>;
  }

  if (!classData) {
    return <div className="error">Class not found</div>;
  }

  if (enrolled) {
    return (
      <div className="enrollment-success">
        <div className="container">
          <div className="success-message">
            <h2>🎉 Enrollment Successful!</h2>
            <p>You've successfully enrolled in <strong>{classData.title}</strong></p>
            <p>Check your dashboard for access details and session information.</p>
            <p>Redirecting to dashboard...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="enrollment-page">
      <div className="container">
        <div className="enrollment-header">
          <h1>Enroll in {classData.title}</h1>
          <p>by {classData.hostId?.firstName} {classData.hostId?.lastName}</p>
        </div>

        <div className="enrollment-content">
          <div className="class-summary">
            <div className="class-info">
              <h3>Class Details</h3>
              <p><strong>Duration:</strong> {selectedDays} days</p>
              <p><strong>Monthly Price:</strong> ${classData.monthlyPrice}</p>
              <p><strong>Category:</strong> {classData.category}</p>
              <p><strong>Students Enrolled:</strong> {classData.totalEnrolled}</p>
            </div>
          </div>

          <Elements stripe={stripePromise}>
            <EnrollmentForm
              classData={classData}
              selectedDays={selectedDays}
              onSuccess={handleEnrollmentSuccess}
            />
          </Elements>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '../hooks/useAuth';
import { Navigate, Link } from 'react-router-dom';
import AnalyticsDashboard from '../components/AnalyticsDashboard';
import RecommendationMetrics from '../components/RecommendationMetrics';
import LoadingSpinner from '../components/LoadingSpinner';
import api from '../utils/api';
import '../styles/Dashboard.css';

export default function HostDashboardPage() {
  const { user, isAuthenticated, loading } = useAuth();
