import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import io from 'socket.io-client';
import HLSPlayer from '../components/HLSPlayer';
import ViewerChat from '../components/ViewerChat';
import StreamMetadata from '../components/StreamMetadata';
import QualitySelector from '../components/QualitySelector';
import '../styles/LiveStreamViewer.css';

export default function LiveStreamViewer() {
  const { streamId } = useParams();
  const navigate = useNavigate();
  const socketRef = useRef(null);

  // Stream state
  const [stream, setStream] = useState(null);
  const [isLive, setIsLive] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Viewer stats
  const [viewers, setViewers] = useState(0);
  const [watchTime, setWatchTime] = useState(0);

  // Chat state
  const [messages, setMessages] = useState([]);
  const [isChatBlocked, setIsChatBlocked] = useState(false);
  const [blockReason, setBlockReason] = useState('');

  // Quality state
  const [selectedQuality, setSelectedQuality] = useState('auto');
  const [availableQualities, setAvailableQualities] = useState([]);

  // Engagement tracking
  const [engagement, setEngagement] = useState(0);
  const joinedAtRef = useRef(Date.now());
  const watchTimeRef = useRef(null);

  // Get auth token
  const token = localStorage.getItem('token');

  // Fetch stream details on mount
  useEffect(() => {
    const fetchStream = async () => {
      try {
        setLoading(true);
        const response = await axios.get(
          `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/streams/${streamId}`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setStream(response.data);
        setIsLive(response.data.status === 'live');
        
        // Set available qualities from stream config
        if (response.data.quality?.bitrates) {
          setAvailableQualities(response.data.quality.bitrates);
        }
        
        // Fetch chat history
        fetchChatHistory();
      } catch (err) {
        console.error('Failed to fetch stream:', err);
        setError('Failed to load stream. Stream may not exist or be archived.');
        setTimeout(() => navigate('/'), 5000);
      } finally {
        setLoading(false);
      }
    };

    if (streamId) {
      fetchStream();
    }
  }, [streamId, token, navigate]);

  // Track viewer join
  useEffect(() => {
    const trackJoin = async () => {
      try {
        await axios.post(
          `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/viewer-join`,
          {
            qualitySelected: selectedQuality,
            browser: getBrowserInfo(),
            os: getOSInfo()
          },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      } catch (err) {
        console.error('Failed to track viewer join:', err);
      }
    };

    if (stream && token) {
      trackJoin();
    }
  }, [stream, streamId, token, selectedQuality]);

  // Initialize Socket.io connection
  useEffect(() => {
    if (!stream || !token) return;

    socketRef.current = io(import.meta.env.VITE_API_URL || 'http://localhost:5000', {
      auth: { token },
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
    });

    // Join stream room
    socketRef.current.emit('stream:join', { streamId });

    // Listen for real-time updates
    socketRef.current.on('stream:viewer-update', (data) => {
      setViewers(data.totalViewers || 0);
    });

    socketRef.current.on('stream:chat-message', (data) => {
      setMessages((prev) => [...prev, data]);
      // Calculate engagement based on chat activity
      setEngagement((prev) => Math.min(prev + 5, 100));
    });

    socketRef.current.on('stream:stats', (data) => {
      if (data.streamHealth?.qualityAvailable) {
        setAvailableQualities(data.streamHealth.qualityAvailable);
      }
    });

    socketRef.current.on('stream:stopped', () => {
      setIsLive(false);
      setTimeout(() => {
        setError('This stream has ended.');
      }, 500);
    });

    socketRef.current.on('stream:quality', (data) => {
      if (data.availableLevels) {
        setAvailableQualities(data.availableLevels);
      }
    });

    return () => {
      if (socketRef.current) {
        socketRef.current.emit('stream:leave', { streamId });
        socketRef.current.disconnect();
      }
    };
  }, [stream, streamId, token]);

  // Start watch time timer
  useEffect(() => {
    watchTimeRef.current = setInterval(() => {
      const elapsed = Math.floor((Date.now() - joinedAtRef.current) / 1000);
      setWatchTime(elapsed);
      
      // Calculate engagement based on watch time
      if (elapsed > 0) {
        setEngagement((prev) => Math.min(prev + 0.5, 100));
      }
    }, 1000);

    return () => clearInterval(watchTimeRef.current);
  }, []);

  // Fetch chat history
  const fetchChatHistory = async () => {
    try {
      const response = await axios.get(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/chat?limit=50`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setMessages(response.data || []);
    } catch (err) {
      console.error('Failed to fetch chat history:', err);
    }
  };

  // Handle sending message
  const handleSendMessage = async (messageText) => {
    try {
      const response = await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/chat`,
        { message: messageText },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (response.status === 403) {
        setIsChatBlocked(true);
        setBlockReason(response.data?.reason || 'You are temporarily muted');
        setTimeout(() => setIsChatBlocked(false), 60000); // 1 minute timeout
      } else {
        // Message sent successfully, increment engagement
        setEngagement((prev) => Math.min(prev + 10, 100));
      }
    } catch (err) {
      if (err.response?.status === 403) {
        setIsChatBlocked(true);
        setBlockReason(err.response.data?.reason || 'You are temporarily muted');
      } else {
        console.error('Failed to send message:', err);
      }
    }
  };

  // Handle quality change
  const handleQualityChange = (quality) => {
    setSelectedQuality(quality);
    if (socketRef.current) {
      socketRef.current.emit('stream:quality', { streamId, quality });
    }
  };

  // Track viewer leave
  const handleBeforeUnload = async () => {
    try {
      await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/viewer-leave`,
        {
          watchTime,
          engagement: Math.round(engagement)
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
    } catch (err) {
      console.error('Failed to track viewer leave:', err);
    }
  };

  useEffect(() => {
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [watchTime, engagement, streamId, token]);

  if (loading) {
    return (
      <div className="livestream-viewer-loading">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading stream...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="livestream-viewer-error">
        <div className="error-message">
          <h2>⚠️ Unable to Load Stream</h2>
          <p>{error}</p>
          <p style={{ fontSize: '0.9rem', color: '#999' }}>Redirecting to home...</p>
        </div>
      </div>
    );
  }

  if (!stream) {
    return (
      <div className="livestream-viewer-error">
        <div className="error-message">
          <h2>Stream not found</h2>
          <p>The stream you're looking for doesn't exist.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="livestream-viewer-page">
      <div className="video-section">
        <HLSPlayer
          streamId={streamId}
          quality={selectedQuality}
          onQualityChange={handleQualityChange}
          isLive={isLive}
        />

        <StreamMetadata
          title={stream.title}
          description={stream.description}
          hostName={stream.hostName}
          hostAvatar={stream.hostAvatar}
          viewers={viewers}
          category={stream.category}
          startedAt={stream.startedAt}
          isLive={isLive}
        />
      </div>

      <div className="sidebar">
        <QualitySelector
          options={availableQualities}
          selected={selectedQuality}
          onChange={handleQualityChange}
        />

        <div className="viewer-stats-card">
          <h3>Stream Info</h3>
          <div className="stat-item">
            <span className="label">Current Viewers</span>
            <span className="value">{viewers}</span>
          </div>
          <div className="stat-item">
            <span className="label">Watch Time</span>
            <span className="value">{formatWatchTime(watchTime)}</span>
          </div>
          <div className="stat-item">
            <span className="label">Engagement</span>
            <div className="engagement-bar">
              <div className="engagement-fill" style={{ width: `${engagement}%` }}></div>
            </div>
          </div>
          <div className="stat-item">
            <span className="label">Status</span>
            <span className={`status-badge ${isLive ? 'live' : 'ended'}`}>
              {isLive ? '🔴 Live' : '⚫ Ended'}
            </span>
          </div>
        </div>
      </div>

      <div className="chat-section">
        <ViewerChat
          streamId={streamId}
          messages={messages}
          onSendMessage={handleSendMessage}
          isModerated={stream.chatModerated}
          isBlocked={isChatBlocked}
          blockReason={blockReason}
        />
      </div>
    </div>
  );
}

// Utility functions
function formatWatchTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes}m`;
  } else if (minutes > 0) {
    return `${minutes}m ${secs}s`;
  } else {
    return `${secs}s`;
  }
}

function getBrowserInfo() {
  const ua = navigator.userAgent;
  if (ua.includes('Chrome')) return 'Chrome';
  if (ua.includes('Firefox')) return 'Firefox';
  if (ua.includes('Safari')) return 'Safari';
  if (ua.includes('Edge')) return 'Edge';
  return 'Unknown';
}

function getOSInfo() {
  const ua = navigator.userAgent;
  if (ua.includes('Windows')) return 'Windows';
  if (ua.includes('Mac')) return 'MacOS';
  if (ua.includes('Linux')) return 'Linux';
  if (ua.includes('iPhone') || ua.includes('iPad')) return 'iOS';
  if (ua.includes('Android')) return 'Android';
  return 'Unknown';
}

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import '../styles/Auth.css';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      await login(email, password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-container">
        <h2>Login</h2>

        {error && <div className="error-message">{error}</div>}

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label htmlFor="login-email">Email</label>
            <input
              id="login-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              placeholder="your@email.com"
            />
          </div>

          <div className="form-group">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              placeholder="Enter your password"
            />
          </div>

          <button type="submit" disabled={loading} className="submit-button">
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>

        <p className="auth-footer">
          Don't have an account? <Link to="/signup">Sign up here</Link>
        </p>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import AnalyticsOverview from '../components/AnalyticsOverview';
import ViewerTimeline from '../components/ViewerTimeline';
import EngagementMetrics from '../components/EngagementMetrics';
import QualityDistribution from '../components/QualityDistribution';
import RetentionCurve from '../components/RetentionCurve';
import DemographicsPanel from '../components/DemographicsPanel';
import '../styles/StreamAnalytics.css';

export default function StreamAnalyticsPage() {
  const { streamId } = useParams();
  const [analytics, setAnalytics] = useState(null);
  const [timelineData, setTimelineData] = useState([]);
  const [engagementData, setEngagementData] = useState(null);
  const [qualityData, setQualityData] = useState(null);
  const [demographics, setDemographics] = useState(null);
  const [retentionData, setRetentionData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [timeRange, setTimeRange] = useState('24h');

  useEffect(() => {
    fetchAnalyticsData();
  }, [streamId, timeRange]);

  const fetchAnalyticsData = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      // Fetch all analytics data in parallel
      const [overview, timeline, engagement, quality, demographics, retention] =
        await Promise.all([
          axios.get(`/api/analytics/live/streams/${streamId}`, { headers }),
          axios.get(`/api/analytics/live/streams/${streamId}/timeline`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/engagement`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/quality`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/demographics`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/retention`, {
            headers,
          }),
        ]);

      setAnalytics(overview.data);
      setTimelineData(timeline.data.timeline || []);
      setEngagementData(engagement.data);
      setQualityData(quality.data);
      setDemographics(demographics.data);
      setRetentionData(retention.data);
      setError(null);
    } catch (err) {
      console.error('Error fetching analytics:', err);
      setError('Failed to load analytics data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="stream-analytics-page">
        <div className="analytics-loading">
          <div className="spinner"></div>
          <p>Loading analytics...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="stream-analytics-page">
        <div className="analytics-error">
          <h2>Error Loading Analytics</h2>
          <p>{error}</p>
          <button onClick={fetchAnalyticsData} className="btn-retry">
            Retry
          </button>
        </div>
      </div>
    );
  }

  if (!analytics) {
    return (
      <div className="stream-analytics-page">
        <div className="analytics-empty">
          <h2>No Analytics Available</h2>
          <p>This stream hasn't been analyzed yet.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="stream-analytics-page">
      <div className="analytics-header">
        <div className="header-content">
          <h1>Stream Analytics</h1>
          <p className="stream-title">{analytics.stream?.title}</p>
          <p className="stream-date">
            {new Date(analytics.stream?.startedAt).toLocaleDateString()} -{' '}
            {new Date(analytics.stream?.startedAt).toLocaleTimeString()}
          </p>
        </div>

        <div className="time-range-selector">
          <label htmlFor="timeRange">Time Range:</label>
          <select
            id="timeRange"
            value={timeRange}
            onChange={(e) => setTimeRange(e.target.value)}
            className="range-select"
          >
            <option value="24h">Last 24 Hours</option>
            <option value="7d">Last 7 Days</option>
            <option value="30d">Last 30 Days</option>
          </select>
        </div>
      </div>

      {/* KPI Cards */}
      <section className="analytics-section">
        <AnalyticsOverview data={analytics.overview} />
      </section>

      {/* Viewer Timeline Chart */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Viewer Timeline</h2>
          <p>Real-time viewer count throughout the stream</p>
        </div>
        <ViewerTimeline data={timelineData} />
      </section>

      {/* Quality Distribution Chart */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Quality Distribution</h2>
          <p>Percentage of viewers per quality level</p>
        </div>
        <QualityDistribution data={qualityData} />
      </section>

      {/* Engagement Metrics */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Engagement Metrics</h2>
          <p>Chat activity and viewer interaction</p>
        </div>
        <EngagementMetrics data={engagementData} />
      </section>

      {/* Retention Curve */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Retention Curve</h2>
          <p>How long viewers stayed during the stream</p>
        </div>
        <RetentionCurve data={retentionData} />
      </section>

      {/* Demographics */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Viewer Demographics</h2>
          <p>Browser, OS, and device breakdown</p>
        </div>
        <DemographicsPanel data={demographics} />
      </section>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import PromptDialog from '../components/PromptDialog';
import { useAuth } from '../context/AuthContext';
import api from '../utils/api';
import '../styles/UserAppeals.css';

const UserAppealsPage = () => {
  const { user } = useAuth();
  const [appeals, setAppeals] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedAppeal, setSelectedAppeal] = useState(null);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [promptOpen, setPromptOpen] = useState(false);
  const [promptTarget, setPromptTarget] = useState(null);

  useEffect(() => {
    fetchAppeals();
  }, []);

  const [eligible, setEligible] = useState([]);

  const fetchAppeals = async () => {
    try {
      setLoading(true);
      const response = await api.get('/moderation/appeals/my-appeals');
      setAppeals(response.data.appeals);

      // Fetch rejected items eligible for appeal
      const rej = await api.get('/moderation/my/rejected');
      setEligible(rej.data.logs || []);
    } catch (error) {
      console.error('Error fetching appeals:', error);
    } finally {
      setLoading(false);
    }
  };

  const submitAppeal = (logId) => {
    setPromptTarget(logId);
    setPromptOpen(true);
  };

  const doSubmitAppeal = async (reason) => {
    if (!reason) return;
    setPromptOpen(false);
    try {
      await api.post(`/moderation/${promptTarget}/appeal`, { reason });
      setSuccess('Appeal submitted');
      setTimeout(() => setSuccess(null), 4000);
      fetchAppeals();
    } catch (err) {
      console.error('Failed to submit appeal', err);
      setError('Failed to submit appeal');
      setTimeout(() => setError(null), 4000);
    }
  };

  if (loading) {
    return <div className="appeals-page"><div className="loading">Loading your appeals...</div></div>;
  }

  return (
    <div className="appeals-page">
      <div className="appeals-header">
        <h1>📋 My Appeals</h1>
        <p>Track and manage your content appeals</p>
      </div>
        {error && <div className="alert alert-error">{error}</div>}
        {success && <div className="alert alert-success">{success}</div>}
        <PromptDialog
          open={promptOpen}
          title="Submit Appeal"
          label="Reason"
          placeholder="Explain why this should be reinstated"
          onConfirm={doSubmitAppeal}
          onCancel={() => setPromptOpen(false)}
          confirmLabel="Submit"
          cancelLabel="Cancel"
        />

      <div className="appeals-section">
        <h2>Eligible to Appeal</h2>
        {eligible.length === 0 ? (
          <p>No recently rejected items to appeal.</p>
        ) : (
          <div className="eligible-list">
            {eligible.map(item => (
              <div key={item._id} className="eligible-card">
                <div className="eligible-meta">
                  <strong>{item.contentType.replace(/_/g, ' ')}</strong>
                  <small>Rejected: {new Date(item.rejectedAt || item.createdAt).toLocaleDateString()}</small>
                </div>
                <div className="eligible-content">{item.content.substring(0, 150)}...</div>
                <div className="eligible-actions">
                  <button onClick={() => submitAppeal(item._id)} className="btn">Submit Appeal</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="appeals-list">
        {appeals.map(appeal => (
          <div
            key={appeal._id}
            className={`appeal-card appeal-${appeal.appeal?.status || 'none'}`}
            onClick={() => setSelectedAppeal(selectedAppeal === appeal._id ? null : appeal._id)}
          >
            <div className="appeal-header">
              <div className="appeal-title">
                <span className="content-type">{appeal.contentType.replace(/_/g, ' ')}</span>
                <span className={`appeal-status status-${appeal.appeal?.status || 'none'}`}>
                  {appeal.appeal?.status ? appeal.appeal.status.toUpperCase() : 'NO APPEAL'}
                </span>
              </div>
              <small className="appeal-date">
                {new Date(appeal.createdAt).toLocaleDateString()}
              </small>
            </div>

            {selectedAppeal === appeal._id && (
              <div className="appeal-details">
                <div className="detail-section">
                  <h4>Original Content</h4>
                  <div className="content-box">
                    {appeal.content}
                  </div>
                </div>

                <div className="detail-section">
                  <h4>Rejection Reason</h4>
                  <p className="reason-text">
                    {appeal.reviewNotes || 'No specific reason provided'}
                  </p>
                </div>

                {appeal.categories && Object.keys(appeal.categories).filter(k => appeal.categories[k]).length > 0 && (
                  <div className="detail-section">
                    <h4>Violation Categories</h4>
                    <div className="categories">
                      {Object.keys(appeal.categories)
                        .filter(k => appeal.categories[k])
                        .map(category => (
                          <span key={category} className="category-badge">
                            {category.replace(/_/g, ' ')}
                          </span>
                        ))}
                    </div>
                  </div>
                )}

                {appeal.appeal?.status === 'pending' && (
                  <div className="detail-section">
                    <h4>Your Appeal</h4>
                    <p className="appeal-text">
                      <strong>Submitted:</strong> {new Date(appeal.appeal.submittedAt).toLocaleDateString()}
                    </p>
                    <p className="appeal-text">
                      <strong>Your Reason:</strong>
                    </p>
                    <div className="content-box">
                      {appeal.appeal.reason}
                    </div>
                    <p className="pending-message">
                      ⏳ Your appeal is being reviewed. You'll receive an email when a decision is made.
                    </p>
                  </div>
                )}

                {appeal.appeal?.status === 'approved' && (
                  <div className="detail-section success">
                    <h4>✅ Appeal Approved</h4>
                    <p>
                      <strong>Decision Date:</strong> {new Date(appeal.appeal.reviewedAt).toLocaleDateString()}
                    </p>
                    <p>
                      Your appeal has been approved. Your content has been restored and is now visible again.
                    </p>
                    {appeal.appeal.appealNotes && (
                      <p>
                        <strong>Admin Notes:</strong> {appeal.appeal.appealNotes}
                      </p>
                    )}
                  </div>
                )}

                {appeal.appeal?.status === 'rejected' && (
                  <div className="detail-section error">
                    <h4>❌ Appeal Rejected</h4>
                    <p>
                      <strong>Decision Date:</strong> {new Date(appeal.appeal.reviewedAt).toLocaleDateString()}
                    </p>
                    <p>
                      Your appeal has been reviewed and rejected. The original decision to reject this content stands.
                    </p>
                    {appeal.appeal.appealNotes && (
                      <p>
                        <strong>Admin Notes:</strong> {appeal.appeal.appealNotes}
                      </p>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

